python3 << 'EOF'
import json

# Load all definitions
ixp_d = json.load(open('/tmp/ixp_invoiceIXP.json'))
ixp_node = ixp_d['Data']['Node']

end_d = json.load(open('/tmp/end_def.json'))
end_node = end_d['Data']['Node']

script_d = json.load(open('/tmp/script_def.json'))
script_node = script_d['Data']['Node']

# Build the full flow
flow = {
  "id": "653c1eba-cff1-43a9-b156-4f2291177401",
  "version": "1.8",
  "name": "InvoiceExtractionFlow",
  "nodes": [
    # Trigger node (CLI-owned, already in file)
    {
      "id": "newVendorInvoiceUploaded1",
      "type": "uipath.connector.trigger.uipath-microsoft-onedrive.file-created",
      "typeVersion": "1.0.0",
      "display": { "label": "New Vendor Invoice Uploaded" },
      "inputs": {
        "entryPointId": "219a3e15-9926-4dee-b023-7b90c24ce0db",
        "isDefaultEntryPoint": True
      }
    },
    # IxP extraction node (user-owned)
    {
      "id": "extractInvoiceFields1",
      "type": "uipath.ixp.invoiceixp-cef0d447-ixp.ff973488-5d89-8035-86ac-f980b4be6deb-c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
      "typeVersion": "1.0.0",
      "display": { "label": "Extract Invoice Fields" },
      "inputs": {
        "model": {
          "id": "ff973488-5d89-8035-86ac-f980b4be6deb",
          "modelName": "invoiceixp-cef0d447-ixp",
          "modelDisplayName": "InvoiceIXP",
          "folderKey": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
