          "folderPath": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
          "description": ""
        },
        "modelName": "invoiceixp-cef0d447-ixp",
        "projectName": "invoiceixp-cef0d447-ixp",
        "folderKey": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
        "folderName": "Shared",
        "versionTag": "",
        "pageRange": "",
        "fileRef": "=js:$vars.newVendorInvoiceUploaded1.output.URL"
      },
      "outputs": {
        "output": ixp_node['outputDefinition']['output'],
        "error": ixp_node['outputDefinition']['error']
      }
    },
    # Script node to reshape IxP output
    {
      "id": "buildSapPayload1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": { "label": "Build SAP Payload" },
      "inputs": {
        "script": """
const fields = $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Fields || [];
function getField(name) {
  const f = fields.find(function(f) { return f.FieldName === name; });
  return f && f.Values && f.Values.length > 0 ? f.Values[0] : null;
}
return {
  invoiceNumber: getField('invoice_number') || getField('InvoiceNumber') || getField('Invoice Number'),
  vendor: getField('vendor') || getField('Vendor') || getField('vendor_name') || getField('Vendor Name'),
  invoiceDate: getField('invoice_date') || getField('InvoiceDate') || getField('Invoice Date'),
  totalAmount: getField('total_amount') || getField('TotalAmount') || getField('Total Amount') || getField('amount_due') || getField('AmountDue'),
  lineItems: ($vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Tables || []).map(function(t) { return t; }),
  sourceFile: $vars.newVendorInvoiceUploaded1.output.FullName,
  documentId: $vars.extractInvoiceFields1.output.ExtractionResult.DocumentId
};
"""
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": script_node['outputDefinition']['error']
      }
    },
    # HTTP POST to SAP (CLI-owned, already in file)
