      "typeVersion": "2.3",
      "display": { "label": "POST to SAP" },
      "inputs": {
        "branches": [],
        "timeout": "PT15M",
        "retryCount": 0
      }
    },
    # End node
    {
      "id": "end1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": { "label": "End" },
      "inputs": {},
      "outputs": {}
    }
  ],
  "edges": [
    {
      "id": "e-trigger-ixp",
      "sourceNodeId": "newVendorInvoiceUploaded1",
      "sourcePort": "output",
      "targetNodeId": "extractInvoiceFields1",
      "targetPort": "input"
    },
    {
      "id": "e-ixp-script",
      "sourceNodeId": "extractInvoiceFields1",
